// ===== DA CAMBIARE UNA VOLTA SOLA =====
const LISTA_BREVO = 2;                       // numero della lista in Brevo (Contatti → Liste)
const MITTENTE = { name: 'FreeLLMArena', email: 'info@freellmarena.com' }; // deve essere verificato in Brevo
// =======================================
const a = $json;
const esc = (s) => String(s || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const link = `${a.link}?utm_source=newsletter&utm_medium=email`;
const testo = a.contentSnippet || a.content || '';
const html = `<!doctype html><html><body style="margin:0;background:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#14202b">
<div style="max-width:560px;margin:0 auto;padding:24px">
<p style="font-size:13px;color:#5b6b7a;margin:0 0 12px">FreeLLMArena · the free AI leaderboard</p>
<h1 style="font-size:24px;line-height:1.25;margin:0 0 12px">${esc(a.title)}</h1>
<p style="font-size:16px;line-height:1.5;margin:0 0 20px">${esc(testo)}</p>
<p style="margin:0 0 28px"><a href="${esc(link)}" style="display:inline-block;background:#0d7a47;color:#fff;text-decoration:none;padding:12px 20px;border-radius:6px;font-weight:bold">Read it on FreeLLMArena</a></p>
<p style="font-size:12px;color:#5b6b7a;line-height:1.5">You get this because you signed up on freellmarena.com. <a href="{{ unsubscribe }}" style="color:#5b6b7a">Unsubscribe</a> · <a href="{{ mirror }}" style="color:#5b6b7a">View in browser</a></p>
</div></body></html>`;
return { json: {
  name: `Blog · ${String(a.title).slice(0, 80)} · ${new Date().toISOString().slice(0, 10)}`,
  subject: String(a.title).slice(0, 150),
  previewText: String(testo).slice(0, 140),
  sender: MITTENTE,
  type: 'classic',
  htmlContent: html,
  recipients: { listIds: [LISTA_BREVO] }
} };
